use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn main () -> Result < () > { let source_dir = Path :: new (".") ; let ngram_sizes = vec ! [2 , 3 , 5] ; let top_k = 5 ; println ! ("🦀 Compiler Layer N-Gram Ontology Generator") ; println ! ("============================================") ; for & n in & ngram_sizes { println ! ("\n📊 Analyzing {}-grams across compiler layers:" , n) ; match analyze_compiler_layers (source_dir , n , top_k) { Ok (ontologies) => { for ontology in & ontologies { println ! ("\n{} {} Layer Analysis:" , ontology . layer . emoji () , match & ontology . layer { CompilerLayer :: AST => "AST" , CompilerLayer :: HIR => "HIR" , CompilerLayer :: MIR => "MIR" , CompilerLayer :: THIR => "THIR" , CompilerLayer :: Parser => "Parser" , CompilerLayer :: Resolve => "Resolve" , CompilerLayer :: TypeCk => "TypeCheck" , CompilerLayer :: Codegen => "Codegen" , CompilerLayer :: Lint => "Lint" , CompilerLayer :: Macro => "Macro" , CompilerLayer :: Other (s) => s , }) ; println ! ("   Total patterns: {}" , ontology . total_patterns) ; println ! ("   Coverage: {:.2}%" , ontology . coverage_percentage) ; for (i , pattern) in ontology . top_patterns . iter () . take (3) . enumerate () { println ! ("   {}. {} \"{}\" (freq: {}, nodes: {})" , i + 1 , pattern . emoji , pattern . pattern , pattern . frequency , pattern . nodes . len ()) ; } if ! ontology . cross_layer_relations . is_empty () { println ! ("   Cross-layer relations:") ; for relation in ontology . cross_layer_relations . iter () . take (2) { println ! ("     → {} \"{}\" (strength: {:.2}, shared: {})" , relation . target_layer . emoji () , relation . pattern , relation . relation_strength , relation . shared_nodes) ; } } } let filename = format ! ("compiler_layer_ontology_{}gram.json" , n) ; let json = serde_json :: to_string_pretty (& ontologies) ? ; fs :: write (& filename , json) ? ; println ! ("\n💾 Saved to {}" , filename) ; } Err (e) => { eprintln ! ("❌ Error analyzing {}-grams: {}" , n , e) ; } } } println ! ("\n🎯 Compiler Layer Ontology Generation Complete!") ; Ok (()) }
}